/*
  ESP32-S3-CAM Robot Car
    Wi-Fi + Camera + L298N + OLED + BLE

      Required:
        ESP32 Arduino core 3.x
          Adafruit GFX
            Adafruit SSD1306

              Board: ESP32S3 Dev Module
              */

              #include <WiFi.h>
              #include <LittleFS.h>
              #include <Wire.h>
              #include <Adafruit_GFX.h>
              #include <Adafruit_SSD1306.h>
              #include "esp_camera.h"
              #include "esp_http_server.h"
              #include <BLEDevice.h>
              #include <BLEServer.h>
              #include <BLEUtils.h>
              #include <BLE2902.h>

              // Wi-Fi credentials
              const char* HOME_SSID = "YourPhoneHotspot";
              const char* HOME_PASS = "YourPassword";
              const char* AP_SSID = "SpyCar";
              const char* AP_PASS = "12345678";

              // L298N pins: verify against your wiring
              #define IN1 1
              #define IN2 2
              #define IN3 14
              #define IN4 42
              #define ENA 41
              #define ENB 47

              // OLED pins
              #define OLED_SDA 21
              #define OLED_SCL 48

              Adafruit_SSD1306 oled(128, 64, &Wire, -1);
              bool oledOk = false;
              bool cameraOk = false;
              bool webHold = false;

              int speedVal = 200;
              unsigned long lastWebCmd = 0;

              httpd_handle_t ctrlServer = NULL;
              httpd_handle_t streamServer = NULL;

              // Camera pins from your original code.
              // These MUST match your exact ESP32-S3-CAM.
              #define PWDN_GPIO_NUM  -1
              #define RESET_GPIO_NUM -1
              #define XCLK_GPIO_NUM  15
              #define SIOD_GPIO_NUM  4
              #define SIOC_GPIO_NUM  5
              #define Y9_GPIO_NUM    16
              #define Y8_GPIO_NUM    17
              #define Y7_GPIO_NUM    18
              #define Y6_GPIO_NUM    12
              #define Y5_GPIO_NUM    10
              #define Y4_GPIO_NUM    8
              #define Y3_GPIO_NUM    9
              #define Y2_GPIO_NUM    11
              #define VSYNC_GPIO_NUM 6
              #define HREF_GPIO_NUM  7
              #define PCLK_GPIO_NUM  13

              // OLED status
              void oledShow(const String& top, const String& message) {
                if (!oledOk) return;

                  oled.clearDisplay();
                    oled.setTextColor(SSD1306_WHITE);
                      oled.setTextSize(1);
                        oled.setCursor(0, 0);
                          oled.print(top);

                            oled.setCursor(0, 28);
                              oled.setTextSize(message.length() <= 10 ? 2 : 1);
                                oled.print(message.substring(0, 21));
                                  oled.display();
                                  }

                                  // Motor control
                                  void setMotor(int a, int b, int en, int value) {
                                    value = constrain(value, -255, 255);

                                      digitalWrite(a, value > 0 ? HIGH : LOW);
                                        digitalWrite(b, value < 0 ? HIGH : LOW);

                                          ledcWrite(en, abs(value));
                                          }

                                          void drive(int left, int right) {
                                            setMotor(IN1, IN2, ENA, left);
                                              setMotor(IN3, IN4, ENB, right);
                                              }

                                              void handleCmd(char c) {
                                                switch (c) {
                                                    case 'F': drive(speedVal, speedVal); break;
                                                        case 'B': drive(-speedVal, -speedVal); break;
                                                            case 'L': drive(-speedVal, speedVal); break;
                                                                case 'R': drive(speedVal, -speedVal); break;
                                                                    case 'S': drive(0, 0); break;

                                                                        case '0':
                                                                              speedVal = 0;
                                                                                    drive(0, 0);
                                                                                          break;

                                                                                              default:
                                                                                                    if (c >= '1' && c <= '9') {
                                                                                                            speedVal = map(c - '0', 1, 9, 90, 255);
                                                                                                                  }
                                                                                                                        break;
                                                                                                                          }
                                                                                                                          }

                                                                                                                          String urlDecode(const char* s) {
                                                                                                                            String result;

                                                                                                                              while (*s) {
                                                                                                                                  if (*s == '+') {
                                                                                                                                        result += ' ';
                                                                                                                                              s++;
                                                                                                                                                  } else if (*s == '%' && s[1] && s[2]) {
                                                                                                                                                        char hex[3] = {s[1], s[2], '\0'};
                                                                                                                                                              result += (char)strtol(hex, NULL, 16);
                                                                                                                                                                    s += 3;
                                                                                                                                                                        } else {
                                                                                                                                                                              result += *s++;
                                                                                                                                                                                  }
                                                                                                                                                                                    }

                                                                                                                                                                                      return result;
                                                                                                                                                                                      }

                                                                                                                                                                                      // Web control page
                                                                                                                                                                                      const char INDEX_HTML[] PROGMEM = R"rawliteral(
                                                                                                                                                                                      <!DOCTYPE html>
                                                                                                                                                                                      <html>
                                                                                                                                                                                      <head>
                                                                                                                                                                                      <meta name="viewport"
                                                                                                                                                                                       content="width=device-width,initial-scale=1,user-scalable=no">
                                                                                                                                                                                       <title>Robot Car</title>
                                                                                                                                                                                       <style>
                                                                                                                                                                                       body{background:#0b0f0b;color:#7CFC7C;font-family:monospace;text-align:center}
                                                                                                                                                                                       .pad{display:grid;grid-template-columns:repeat(3,76px);gap:8px;justify-content:center}
                                                                                                                                                                                       button{height:76px;font-size:25px;background:#112211;color:#7CFC7C;border-radius:12px}
                                                                                                                                                                                       .stop{background:#441111;color:#ff7777}
                                                                                                                                                                                       .box{position:relative;width:100%;max-width:640px;margin:auto}
                                                                                                                                                                                       .box img,.box canvas{width:100%;display:block}
                                                                                                                                                                                       .box canvas{position:absolute;top:0;left:0}
                                                                                                                                                                                       </style>
                                                                                                                                                                                       </head>
                                                                                                                                                                                       <body>
                                                                                                                                                                                       <h3>ROBOT CAR</h3>
                                                                                                                                                                                       <div id="st">Starting...</div>

                                                                                                                                                                                       <div class="box">
                                                                                                                                                                                       <img id="cam">
                                                                                                                                                                                       <canvas id="ov"></canvas>
                                                                                                                                                                                       </div>

                                                                                                                                                                                       <div class="pad">
                                                                                                                                                                                       <span></span><button id="F">▲</button><span></span>
                                                                                                                                                                                       <button id="L">◀</button><button id="S" class="stop">■</button><button id="R">▶</button>
                                                                                                                                                                                       <span></span><button id="B">▼</button><span></span>
                                                                                                                                                                                       </div>

                                                                                                                                                                                       Speed <input id="sp" type="range" min="0" max="9" value="7">

                                                                                                                                                                                       <script>
                                                                                                                                                                                       const $=id=>document.getElementById(id);
                                                                                                                                                                                       $('cam').src='http://'+location.hostname+':81/stream';

                                                                                                                                                                                       let timer=null;
                                                                                                                                                                                       function send(c){
                                                                                                                                                                                         fetch('/cmd?c='+c).catch(()=>{});
                                                                                                                                                                                         }
                                                                                                                                                                                         function start(c){
                                                                                                                                                                                           send(c);
                                                                                                                                                                                             clearInterval(timer);
                                                                                                                                                                                               timer=setInterval(()=>send(c),250);
                                                                                                                                                                                               }
                                                                                                                                                                                               function stop(){
                                                                                                                                                                                                 clearInterval(timer);
                                                                                                                                                                                                   timer=null;
                                                                                                                                                                                                     send('S');
                                                                                                                                                                                                     }

                                                                                                                                                                                                     ['F','B','L','R'].forEach(id=>{
                                                                                                                                                                                                       const b=$(id);
                                                                                                                                                                                                         b.addEventListener('touchstart',e=>{
                                                                                                                                                                                                             e.preventDefault();start(id);
                                                                                                                                                                                                               },{passive:false});
                                                                                                                                                                                                                 b.addEventListener('touchend',e=>{
                                                                                                                                                                                                                     e.preventDefault();stop();
                                                                                                                                                                                                                       },{passive:false});
                                                                                                                                                                                                                         b.addEventListener('touchcancel',stop);
                                                                                                                                                                                                                           b.addEventListener('mousedown',()=>start(id));
                                                                                                                                                                                                                             b.addEventListener('mouseup',stop);
                                                                                                                                                                                                                               b.addEventListener('mouseleave',()=>{if(timer)stop()});
                                                                                                                                                                                                                               });

                                                                                                                                                                                                                               $('S').onclick=stop;
                                                                                                                                                                                                                               $('sp').oninput=e=>send(e.target.value);
                                                                                                                                                                                                                               $('st').textContent='Camera control ready';
                                                                                                                                                                                                                               </script>
                                                                                                                                                                                                                               </body>
                                                                                                                                                                                                                               </html>
                                                                                                                                                                                                                               )rawliteral";

                                                                                                                                                                                                                               // HTTP handlers
                                                                                                                                                                                                                               esp_err_t indexHandler(httpd_req_t* req) {
                                                                                                                                                                                                                                 httpd_resp_set_type(req, "text/html");
                                                                                                                                                                                                                                   return httpd_resp_send(req, INDEX_HTML, HTTPD_RESP_USE_STRLEN);
                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                   esp_err_t cmdHandler(httpd_req_t* req) {
                                                                                                                                                                                                                                     char query[64]={0};
                                                                                                                                                                                                                                       char value[8]={0};

                                                                                                                                                                                                                                         if (httpd_req_get_url_query_str(
                                                                                                                                                                                                                                                 req,query,sizeof(query)) == ESP_OK &&
                                                                                                                                                                                                                                                       httpd_query_key_value(
                                                                                                                                                                                                                                                               query,"c",value,sizeof(value)) == ESP_OK) {

                                                                                                                                                                                                                                                                   char c=value[0];
                                                                                                                                                                                                                                                                       handleCmd(c);

                                                                                                                                                                                                                                                                           webHold=(c=='F'||c=='B'||c=='L'||c=='R');
                                                                                                                                                                                                                                                                               lastWebCmd=millis();
                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                   return httpd_resp_send(req,"ok",HTTPD_RESP_USE_STRLEN);
                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                   esp_err_t streamHandler(httpd_req_t* req) {
                                                                                                                                                                                                                                                                                     if (!cameraOk) {
                                                                                                                                                                                                                                                                                         httpd_resp_send_err(
                                                                                                                                                                                                                                                                                               req,HTTPD_503_SERVICE_UNAVAILABLE,"Camera unavailable");
                                                                                                                                                                                                                                                                                                   return ESP_FAIL;
                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                       httpd_resp_set_type(
                                                                                                                                                                                                                                                                                                           req,"multipart/x-mixed-replace;boundary=frame");
                                                                                                                                                                                                                                                                                                             httpd_resp_set_hdr(
                                                                                                                                                                                                                                                                                                                 req,"Access-Control-Allow-Origin","*");

                                                                                                                                                                                                                                                                                                                   char header[96];

                                                                                                                                                                                                                                                                                                                     while (true) {
                                                                                                                                                                                                                                                                                                                         camera_fb_t* fb=esp_camera_fb_get();

                                                                                                                                                                                                                                                                                                                             if (!fb) {
                                                                                                                                                                                                                                                                                                                                   vTaskDelay(pdMS_TO_TICKS(20));
                                                                                                                                                                                                                                                                                                                                         continue;
                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                 int n=snprintf(header,sizeof(header),
                                                                                                                                                                                                                                                                                                                                                       "\r\n--frame\r\nContent-Type: image/jpeg\r\nContent-Length: %u\r\n\r\n",
                                                                                                                                                                                                                                                                                                                                                             (unsigned int)fb->len);

                                                                                                                                                                                                                                                                                                                                                                 esp_err_t err=httpd_resp_send_chunk(req,header,n);

                                                                                                                                                                                                                                                                                                                                                                     if (err==ESP_OK) {
                                                                                                                                                                                                                                                                                                                                                                           err=httpd_resp_send_chunk(
                                                                                                                                                                                                                                                                                                                                                                                   req,(const char*)fb->buf,fb->len);
                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                           esp_camera_fb_return(fb);

                                                                                                                                                                                                                                                                                                                                                                                               if (err!=ESP_OK) break;
                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                   return ESP_OK;
                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                   bool initCamera() {
                                                                                                                                                                                                                                                                                                                                                                                                     camera_config_t c={};

                                                                                                                                                                                                                                                                                                                                                                                                       c.ledc_channel=LEDC_CHANNEL_0;
                                                                                                                                                                                                                                                                                                                                                                                                         c.ledc_timer=LEDC_TIMER_0;

                                                                                                                                                                                                                                                                                                                                                                                                           c.pin_d0=Y2_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                             c.pin_d1=Y3_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                               c.pin_d2=Y4_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                 c.pin_d3=Y5_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                   c.pin_d4=Y6_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                     c.pin_d5=Y7_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                       c.pin_d6=Y8_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                         c.pin_d7=Y9_GPIO_NUM;

                                                                                                                                                                                                                                                                                                                                                                                                                           c.pin_xclk=XCLK_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                             c.pin_pclk=PCLK_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                               c.pin_vsync=VSYNC_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                                 c.pin_href=HREF_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                                   c.pin_sccb_sda=SIOD_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                                     c.pin_sccb_scl=SIOC_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                                       c.pin_pwdn=PWDN_GPIO_NUM;
                                                                                                                                                                                                                                                                                                                                                                                                                                         c.pin_reset=RESET_GPIO_NUM;

                                                                                                                                                                                                                                                                                                                                                                                                                                           c.xclk_freq_hz=20000000;
                                                                                                                                                                                                                                                                                                                                                                                                                                             c.pixel_format=PIXFORMAT_JPEG;
                                                                                                                                                                                                                                                                                                                                                                                                                                               c.frame_size=FRAMESIZE_VGA;
                                                                                                                                                                                                                                                                                                                                                                                                                                                 c.jpeg_quality=12;
                                                                                                                                                                                                                                                                                                                                                                                                                                                   c.fb_count=2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                     c.fb_location=CAMERA_FB_IN_PSRAM;
                                                                                                                                                                                                                                                                                                                                                                                                                                                       c.grab_mode=CAMERA_GRAB_LATEST;

                                                                                                                                                                                                                                                                                                                                                                                                                                                         esp_err_t err=esp_camera_init(&c);

                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (err!=ESP_OK) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                               Serial.printf("Camera error: 0x%x\n",(unsigned int)err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // BLE control
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       #define SERVICE_UUID "6E400001-B5A3-F393-E0A9-E50E24DCCA9E"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       #define RX_UUID      "6E400002-B5A3-F393-E0A9-E50E24DCCA9E"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       #define TX_UUID      "6E400003-B5A3-F393-E0A9-E50E24DCCA9E"

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       class RxCb : public BLECharacteristicCallbacks {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         void onWrite(BLECharacteristic* ch) override {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             String value=ch->getValue();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 for (size_t i=0;i<value.length();i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       handleCmd((char)toupper((unsigned char)value[i]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               webHold=false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 class SrvCb : public BLEServerCallbacks {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   void onDisconnect(BLEServer* server) override {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       drive(0,0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           server->getAdvertising()->start();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             void startBLE() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               BLEDevice::init("RobotCar-BLE");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 BLEServer* server=BLEDevice::createServer();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   server->setCallbacks(new SrvCb());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     BLEService* service=server->createService(SERVICE_UUID);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       BLECharacteristic* tx=service->createCharacteristic(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           TX_UUID,BLECharacteristic::PROPERTY_NOTIFY);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             tx->addDescriptor(new BLE2902());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               BLECharacteristic* rx=service->createCharacteristic(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   RX_UUID,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       BLECharacteristic::PROPERTY_WRITE |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           BLECharacteristic::PROPERTY_WRITE_NR);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             rx->setCallbacks(new RxCb());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               service->start();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 server->getAdvertising()->addServiceUUID(SERVICE_UUID);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   server->getAdvertising()->start();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // Setup
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   void setup() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     Serial.begin(115200);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       delay(300);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         Wire.begin(OLED_SDA,OLED_SCL);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           oledOk=oled.begin(SSD1306_SWITCHCAPVCC,0x3C);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             oledShow("ROBOT CAR","Starting");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               pinMode(IN1,OUTPUT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 pinMode(IN2,OUTPUT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   pinMode(IN3,OUTPUT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     pinMode(IN4,OUTPUT);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       digitalWrite(IN1,LOW);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         digitalWrite(IN2,LOW);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           digitalWrite(IN3,LOW);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             digitalWrite(IN4,LOW);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ledcAttach(ENA,1000,8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ledcAttach(ENB,1000,8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   drive(0,0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (!LittleFS.begin(true)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         Serial.println("LittleFS failed");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             cameraOk=initCamera();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WiFi.mode(WIFI_STA);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WiFi.begin(HOME_SSID,HOME_PASS);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unsigned long startTime=millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     while (WiFi.status()!=WL_CONNECTED &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              millis()-startTime<10000) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  delay(250);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      String ip;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (WiFi.status()==WL_CONNECTED) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ip=WiFi.localIP().toString();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WiFi.disconnect(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      delay(100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          WiFi.mode(WIFI_AP);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              WiFi.softAP(AP_SSID,AP_PASS);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ip=WiFi.softAPIP().toString();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.print("Connect to Wi-Fi: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println(AP_SSID);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("Password: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println(AP_PASS);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      httpd_config_t config=HTTPD_DEFAULT_CONFIG();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        config.stack_size=8192;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          config.max_open_sockets=5;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            config.lru_purge_enable=true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              httpd_uri_t indexUri={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "/",HTTP_GET,indexHandler,NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      httpd_uri_t commandUri={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "/cmd",HTTP_GET,cmdHandler,NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (httpd_start(&ctrlServer,&config)==ESP_OK) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  httpd_register_uri_handler(ctrlServer,&indexUri);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      httpd_register_uri_handler(ctrlServer,&commandUri);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          config.server_port=81;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            config.ctrl_port+=1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              config.max_open_sockets=3;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                httpd_uri_t cameraUri={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "/stream",HTTP_GET,streamHandler,NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (httpd_start(&streamServer,&config)==ESP_OK) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            httpd_register_uri_handler(streamServer,&cameraUri);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                startBLE();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print("Open http://");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println(ip);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      oledShow(ip,cameraOk?"Ready":"Camera error");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      void loop() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (webHold && millis()-lastWebCmd>700) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            drive(0,0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                webHold=false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delay(20);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
